from typing import Any, List

class Checker:
    def triangleNumber(self, nums: List[int], result: Any) -> bool:
        if not isinstance(result, int):
            return False
        arr = sorted(nums)
        n = len(arr)
        expected = 0
        for i in range(n - 1, -1, -1):
            left, right = 0, i - 1
            while left < right:
                if arr[left] + arr[right] > arr[i]:
                    expected += right - left
                    right -= 1
                else:
                    left += 1
        return result == expected

